# O(n) extra: a new list of n items
def reverse_copy(nums):
    return nums[::-1]

# O(1) extra: just two indexes
def reverse_in_place(nums):
    i, j = 0, len(nums) - 1
    while i < j:
        nums[i], nums[j] = nums[j], nums[i]
        i += 1
        j -= 1

# O(n) extra: n frames on the call stack
def depth(n):
    return 0 if n == 0 else 1 + depth(n - 1)

# Brute force: check every pair
# O(n^2) time, O(1) extra space
def has_pair_sum(nums, target):
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == target:
                return True
    return False

# Better: remember what you have seen
# O(n) time, O(n) extra space
def has_pair_sum_fast(nums, target):
    seen = set()
    for x in nums:
        if target - x in seen:  # O(1) avg
            return True
        seen.add(x)
    return False

